func TestRouteOnceCtrlRReadsAgainAndTheTraceUsesTheNewReading(t *testing.T) {
	m, env := routeOnceModel(t, &fakeEngine{})
	m = runDiagnostics(t, m, onceHostA)
	m, cmd := step(t, m, testutil.Key("ctrl+r"))
	m = runStages(t, m, cmd)
